#pragma once
#include <juce_core/juce_core.h>
#include <vector>

// Factory library (resources/presets.json, generated by tools/gen_presets.py).
struct Preset
{
    juce::String name, category, notes;
    juce::NamedValueSet values;          // parameter id -> number or choice name
    juce::var lanes;                     // optional: [[gate string, value list], ...] for pattern A
    juce::var lfoShapes;                 // optional: { "1": [16 values], ... }
};

class PresetLibrary
{
public:
    static const PresetLibrary& get();
    const std::vector<Preset>& all() const { return presets; }
    juce::StringArray categories;
private:
    PresetLibrary();
    std::vector<Preset> presets;
};
